import { Component } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { SPACING, SIZE_GROUPS, RADIUS, readCssVar } from '../sg-tokens';

@Component({
  selector: 'sg-spacing',
  imports: [TranslateModule],
  template: `
    <h1 class="sg-h">{{ 'sg.nav.spacing' | translate }}</h1>
    <p class="sg-desc">{{ 'sg.spacing.desc' | translate }}</p>

    <section class="sg-group">
      <h2 class="sg-group-h">Spacing · 4px base</h2>
      <div class="bars">
        @for (t of spacing; track t.var) {
          <div class="bar-row">
            <span class="bar-name">{{ t.label }}</span>
            <span class="bar" [style.width]="'var(' + t.var + ')'"></span>
            <span class="bar-val">{{ val(t.var) }}</span>
          </div>
        }
      </div>
    </section>

    @for (g of sizes; track g.label) {
      <section class="sg-group">
        <h2 class="sg-group-h">{{ g.label }}</h2>
        <div class="chips">
          @for (t of g.items; track t.var) {
            <div class="chip">
              <span class="dot" [style.width]="'var(' + t.var + ')'" [style.height]="'var(' + t.var + ')'"></span>
              <span class="chip-name">{{ t.label }}</span>
              <span class="chip-val">{{ val(t.var) }}</span>
            </div>
          }
        </div>
      </section>
    }

    <section class="sg-group">
      <h2 class="sg-group-h">Radius</h2>
      <div class="chips">
        @for (t of radius; track t.var) {
          <div class="chip">
            <span class="rbox" [style.borderRadius]="'var(' + t.var + ')'"></span>
            <span class="chip-name">{{ t.label }}</span>
            <span class="chip-val">{{ val(t.var) }}</span>
          </div>
        }
      </div>
    </section>
  `,
  styleUrls: ['../sg-page.css'],
  styles: [`
    .bars { display: flex; flex-direction: column; gap: 6px; }
    .bar-row { display: flex; align-items: center; gap: 16px; }
    .bar-name { width: 90px; font-size: var(--fs-13); color: var(--text-body); font-variant-numeric: tabular-nums; }
    .bar { height: 16px; background: var(--primary-base); border-radius: var(--radius-xs); flex-shrink: 0; }
    .bar-val { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }

    .chips { display: flex; flex-wrap: wrap; gap: 20px; align-items: flex-end; }
    .chip { display: flex; flex-direction: column; align-items: center; gap: 6px; min-width: 72px; }
    .dot { background: var(--primary-bg-soft); border: 1px solid var(--primary-border); border-radius: var(--radius-full); }
    .rbox { width: 56px; height: 56px; background: var(--primary-bg-soft); border: 1px solid var(--primary-border); }
    .chip-name { font-size: var(--fs-12); font-weight: 500; color: var(--text-body); }
    .chip-val { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }
  `],
})
export class SgSpacing {
  protected readonly spacing = SPACING;
  protected readonly sizes = SIZE_GROUPS;
  protected readonly radius = RADIUS;
  protected val(v: string): string { return readCssVar(v); }
}
